WITH windows AS (SELECT 0 AS sample, 24460 AS pid, 15170430000000 AS start_ns, 15172792628415 AS end_ns UNION ALL SELECT 1 AS sample, 24460 AS pid, 15173890000000 AS start_ns, 15176192725917 AS end_ns UNION ALL SELECT 2 AS sample, 24460 AS pid, 15177010000000 AS start_ns, 15179306007124 AS end_ns UNION ALL SELECT 3 AS sample, 24460 AS pid, 15180220000000 AS start_ns, 15182484283709 AS end_ns UNION ALL SELECT 4 AS sample, 24460 AS pid, 15183420000000 AS start_ns, 15185678034084 AS end_ns UNION ALL SELECT 5 AS sample, 24460 AS pid, 15186620000000 AS start_ns, 15188881868708 AS end_ns UNION ALL SELECT 6 AS sample, 24460 AS pid, 15189700000000 AS start_ns, 15191972605875 AS end_ns UNION ALL SELECT 7 AS sample, 24460 AS pid, 15193010000000 AS start_ns, 15195280789165 AS end_ns UNION ALL SELECT 8 AS sample, 24460 AS pid, 15196150000000 AS start_ns, 15198477058750 AS end_ns UNION ALL SELECT 9 AS sample, 24460 AS pid, 15199540000000 AS start_ns, 15201822639083 AS end_ns UNION ALL SELECT 10 AS sample, 24460 AS pid, 15202650000000 AS start_ns, 15204934035000 AS end_ns UNION ALL SELECT 11 AS sample, 24460 AS pid, 15205920000000 AS start_ns, 15208220204000 AS end_ns UNION ALL SELECT 12 AS sample, 24460 AS pid, 15209080000000 AS start_ns, 15211355679749 AS end_ns UNION ALL SELECT 13 AS sample, 24460 AS pid, 15212340000000 AS start_ns, 15214688991958 AS end_ns UNION ALL SELECT 14 AS sample, 24460 AS pid, 15215560000000 AS start_ns, 15217904146207 AS end_ns UNION ALL SELECT 15 AS sample, 24460 AS pid, 15218840000000 AS start_ns, 15221118793500 AS end_ns UNION ALL SELECT 16 AS sample, 24460 AS pid, 15222090000000 AS start_ns, 15224373697250 AS end_ns UNION ALL SELECT 17 AS sample, 24460 AS pid, 15225380000000 AS start_ns, 15227643866707 AS end_ns UNION ALL SELECT 18 AS sample, 24460 AS pid, 15228720000000 AS start_ns, 15230977884791 AS end_ns UNION ALL SELECT 19 AS sample, 24460 AS pid, 15231950000000 AS start_ns, 15234208286792 AS end_ns UNION ALL SELECT 20 AS sample, 24460 AS pid, 15235060000000 AS start_ns, 15237326921750 AS end_ns UNION ALL SELECT 21 AS sample, 24460 AS pid, 15238410000000 AS start_ns, 15240662701750 AS end_ns)
SELECT w.sample, count(*) AS app_frame_records,
 sum(CASE WHEN a.jank_type LIKE '%App Deadline Missed%' THEN 1 ELSE 0 END) AS app_deadline_misses,
 sum(CASE WHEN a.jank_type != 'None' THEN 1 ELSE 0 END) AS all_jank_records,
 sum(CASE WHEN a.present_type = 'Dropped Frame' THEN 1 ELSE 0 END) AS dropped_frame_records,
 round(avg(a.dur)/1e6,2) AS mean_actual_frame_ms,
 round(max(a.dur)/1e6,2) AS max_actual_frame_ms,
 group_concat(a.dur) AS actual_durations_ns
FROM windows w JOIN process p ON p.pid=w.pid
JOIN actual_frame_timeline_slice a ON a.upid=p.upid
WHERE a.ts >= w.start_ns AND a.ts < w.end_ns AND a.dur > 0
GROUP BY w.sample ORDER BY w.sample